      advKnob: 'position: absolute; top: 2px; width: 12px; height: 12px; border-radius: 999px; background: #e6e9ef; transition: left 150ms ease-out; left: ' + (ADV ? '16px' : '2px'),
      scoreHead: ADV ? 'Sure' : '', groupedHead: ADV ? 'Grouped by · the weight of each comparison' : 'Grouped by', resetTune: () => self.setState({ thr: C.defaults() }),
